parameters.query:
SELECT m.id, m.model
FROM active_model a
JOIN models m ON m.id = a.model_id;

parameters.jsCode:
const tokenize = text => {
  const words = (String(text).toLowerCase().normalize('NFKD').replace(/[̀-ͯ]/g, '').match(/[a-z0-9]+/g) || [])
    .filter(w => w.length >= 2);
  const out = words.slice();
  for (let i = 0; i < words.length - 1; i++) out.push(words[i] + '_' + words[i + 1]);   // unigrams and bigrams
  return out;
};
const has = (o, k) => Object.prototype.hasOwnProperty.call(o, k);
// Naive Bayes posterior. Returns null when no word of the text is known to the model.
const scoreText = (model, text) => {
  const counts = new Map();
  for (const t of tokenize(text)) if (has(model.vocab, t)) counts.set(t, (counts.get(t) || 0) + 1);
  let matched = 0;
  const score = model.log_prior.slice();
  for (const [t, n] of counts) {
    matched += n;
    const ll = model.vocab[t];
    for (let c = 0; c < score.length; c++) score[c] += n * ll[c];
  }
  if (!matched) return null;
  // Naive Bayes is over-confident on long texts: soften the posterior with a length-based temperature
  const T = Math.max(1, matched / 8);
  const max = Math.max(...score);
  const exps = score.map(s => Math.exp((s - max) / T));
  const Z = exps.reduce((a, b) => a + b, 0);
  return { matched, probs: exps.map(e => e / Z) };
};
const LOW_CONFIDENCE = 0.6;   // below this the answer is flagged for human review
const row = $input.first().json;
const text = $('Validate Predict').first().json.text;
const model = row.model;
const r = scoreText(model, text);
if (!r) {
  return [{ json: { model_id: row.id, label: null, confidence: 0, low_confidence: true,
    alternatives: [], probs_json: '[]', reason: 'no known words in the text' } }];
}
const ranked = model.classes.map((label, i) => ({ label, probability: Math.round(r.probs[i] * 10000) / 10000 }))
  .sort((a, b) => b.probability - a.probability);
return [{ json: {
  model_id: row.id,
  label: ranked[0].label,
  confidence: ranked[0].probability,
  low_confidence: ranked[0].probability < LOW_CONFIDENCE,
  alternatives: ranked.slice(0, 3),
  probs_json: JSON.stringify(ranked.slice(0, 5)),
  reason: null
} }];

parameters.query:
INSERT INTO predictions (model_id, text, label, confidence, low_confidence, probs)
VALUES ($1::int, left($2::text, 2000), $3::text, $4::numeric, $5::boolean, $6::jsonb)
RETURNING id;

parameters.jsCode:
const b = $input.first().json.body || {};
const id = Number(b.prediction_id);
const label = typeof b.label === 'string' ? b.label.trim() : '';
if (!Number.isInteger(id) || id < 1 || id > 9007199254740991) return [{ json: { valid: false, reason: 'prediction_id must be a positive integer' } }];
if (!/^[A-Za-z0-9][A-Za-z0-9 _.-]{0,49}$/.test(label)) return [{ json: { valid: false, reason: 'label must be 1-50 characters: letters, digits, space, dot, dash, underscore' } }];
return [{ json: { valid: true, prediction_id: id, label } }];

const b = $input.first().json.body || {};
const list = Array.isArray(b.examples) ? b.examples : null;
if (!list || list.length < 1 || list.length > 200) return [{ json: { valid: false, reason: 'examples must be an array of 1 to 200 items' } }];
const seen = new Map();
for (const [i, e] of list.entries()) {
  const text = e && typeof e.text === 'string' ? e.text.replace(/\u0000/g, '').trim() : '';
  const label = e && typeof e.label === 'string' ? e.label.trim() : '';
  if (!text || text.length > 2000) return [{ json: { valid: false, reason: 'examples[' + i + '].text must be 1-2000 characters' } }];
  if (!/^[A-Za-z0-9][A-Za-z0-9 _.-]{0,49}$/.test(label)) return [{ json: { valid: false, reason: 'examples[' + i + '].label is invalid' } }];
  seen.set(text, label);   // the last label for a repeated text wins
}
return [{ json: { valid: true, examples_json: JSON.stringify([...seen].map(([text, label]) => ({ text, label }))) } }];

