SELECT m.id, m.model
FROM active_model a
JOIN models m ON m.id = a.model_id;

parameters.jsCode:
const tokenize = text => {
  const words = (String(text).toLowerCase().normalize('NFKD').replace(/[̀-ͯ]/g, '').match(/[a-z0-9]+/g) || [])
    .filter(w => w.length >= 2);
  const out = words.slice();
  for (let i = 0; i < words.length - 1; i++) out.push(words[i] + '_' + words[i + 1]);   // unigrams and bigrams
  return out;
};
const has = (o, k) => Object.prototype.hasOwnProperty.call(o, k);
// Naive Bayes posterior. Returns null when no word of the text is known to the model.
const scoreText = (model, text) => {
  const counts = new Map();
  for (const t of tokenize(text)) if (has(model.vocab, t)) counts.set(t, (counts.get(t) || 0) + 1);
  let matched = 0;
  const score = model.log_prior.slice();
  for (const [t, n] of counts) {
    matched += n;
    const ll = model.vocab[t];
    for (let c = 0; c < score.length; c++) score[c] += n * ll[c];
  }
  if (!matched) return null;
  // Naive Bayes is over-confident on long texts: soften the posterior with a length-based temperature
  const T = Math.max(1, matched / 8);
  const max = Math.max(...score);
  const exps = score.map(s => Math.exp((s - max) / T));
  const Z = exps.reduce((a, b) => a + b, 0);
  return { matched, probs: exps.map(e => e / Z) };
};
const MIN_EXAMPLES = 30, MIN_PER_CLASS = 5, MIN_TEST = 10;
const MIN_ACCURACY = 0.6;      // a model below this is never promoted
const TOLERANCE = 0.005;       // challenger may be this much worse in macro F1 and still replace the champion
const MAX_FEATURES = 4000, ALPHA = 1, TEST_MOD = 5;   // 1 of 5 examples (by id hash) is the fixed holdout

const rows = $('Load Examples').all().map(i => i.json).filter(r => r && r.id !== undefined && r.text && r.label);
const champRow = $('Load Champion').first().json;
const champion = champRow && champRow.model ? champRow.model : null;

const result = o => [{ json: { trained: false, decision: 'skipped', promoted: false, n_train: 0, n_test: 0,
  classes_json: '[]', metrics_json: '{}', champion_metrics_json: 'null', model_json: 'null', ...o } }];

// 1. keep classes with enough examples
const perClass = {};
for (const r of rows) perClass[r.label] = (perClass[r.label] || 0) + 1;
const keep = new Set(Object.keys(perClass).filter(l => perClass[l] >= MIN_PER_CLASS));
const dropped = Object.keys(perClass).filter(l => !keep.has(l));
let data = rows.filter(r => keep.has(r.label));
if (data.length < MIN_EXAMPLES || keep.size < 2) {
  return result({ reason: 'Not enough data: need ' + MIN_EXAMPLES + ' examples in at least 2 classes with ' + MIN_PER_CLASS + '+ examples each (have ' + data.length + ' in ' + keep.size + ')', dropped });
}

// 2. fixed split by id hash: an example never moves between train and holdout
const isTest = r => (Math.imul(Number(r.id) | 0, 2654435761 | 0) >>> 0) % TEST_MOD === 0;
let train = data.filter(r => !isTest(r)), test = data.filter(isTest);
const trainPerClass = {};
for (const r of train) trainPerClass[r.label] = (trainPerClass[r.label] || 0) + 1;
const classes = [...keep].filter(l => (trainPerClass[l] || 0) >= 2).sort();
if (classes.length < 2) return result({ reason: 'Fewer than 2 classes have enough training examples after the split', dropped });
train = train.filter(r => classes.includes(r.label));
test = test.filter(r => classes.includes(r.label));
if (test.length < MIN_TEST) return result({ reason: 'Holdout too small (' + test.length + ' examples, need ' + MIN_TEST + ')', dropped });

// 3. train multinomial Naive Bayes on unigrams and bigrams
const df = new Map();
const docs = train.map(r => ({ c: classes.indexOf(r.label), toks: tokenize(r.text) }));
for (const d of docs) for (const t of new Set(d.toks)) df.set(t, (df.get(t) || 0) + 1);
const vocabList = [...df.entries()].filter(([, n]) => n >= 2).sort((a, b) => b[1] - a[1] || (a[0] < b[0] ? -1 : 1)).slice(0, MAX_FEATURES).map(([t]) => t);
if (!vocabList.length) return result({ reason: 'No word appears in at least 2 training examples', dropped });
const idx = new Map(vocabList.map((t, i) => [t, i]));
const tc = classes.map(() => new Float64Array(vocabList.length));
const total = classes.map(() => 0);
const nDocs = classes.map(() => 0);
for (const d of docs) {
  nDocs[d.c]++;
  for (const t of d.toks) { const i = idx.get(t); if (i !== undefined) { tc[d.c][i]++; total[d.c]++; } }
}
const V = vocabList.length;
const r4 = x => Math.round(x * 1e4) / 1e4;
const vocab = {};
vocabList.forEach((t, i) => { vocab[t] = classes.map((_, c) => r4(Math.log((tc[c][i] + ALPHA) / (total[c] + ALPHA * V)))); });
const model = { algo: 'multinomial_naive_bayes', classes, log_prior: nDocs.map(n => r4(Math.log(n / docs.length))), vocab };

// 4. evaluate on the holdout
const evaluate = (m) => {
  const cls = [...new Set([...classes, ...(m ? m.classes : [])])];
  const tp = {}, fp = {}, fn = {}, sup = {};
  for (const c of cls) { tp[c] = 0; fp[c] = 0; fn[c] = 0; sup[c] = 0; }
  let right = 0;
  for (const r of test) {
    const s = m ? scoreText(m, r.text) : null;
    const pred = s ? m.classes[s.probs.indexOf(Math.max(...s.probs))] : null;
    sup[r.label]++;
    if (pred === r.label) { right++; tp[r.label]++; } else { fn[r.label]++; if (pred !== null) fp[pred]++; }
  }
  const per = {}; let f1sum = 0, n = 0;
  for (const c of cls) {
    if (!sup[c] && !fp[c]) continue;
    const p = tp[c] + fp[c] ? tp[c] / (tp[c] + fp[c]) : 0, rc = sup[c] ? tp[c] / sup[c] : 0;
    const f1 = p + rc ? 2 * p * rc / (p + rc) : 0;
    per[c] = { precision: r4(p), recall: r4(rc), f1: r4(f1), support: sup[c] };
    if (sup[c]) { f1sum += f1; n++; }
  }
  return { accuracy: r4(right / test.length), macro_f1: r4(n ? f1sum / n : 0), per_class: per };
};
const metrics = evaluate(model);
const champMetrics = champion ? evaluate(champion) : null;

// 5. promotion gate
let promoted, reason;
if (metrics.accuracy < MIN_ACCURACY) { promoted = false; reason = 'Accuracy ' + metrics.accuracy + ' is below the minimum ' + MIN_ACCURACY; }
else if (!champion) { promoted = true; reason = 'First model'; }
else if (metrics.macro_f1 >= champMetrics.macro_f1 - TOLERANCE) { promoted = true; reason = 'Macro F1 ' + metrics.macro_f1 + ' vs champion ' + champMetrics.macro_f1 + ' on the same holdout'; }
else { promoted = false; reason = 'Challenger macro F1 ' + metrics.macro_f1 + ' is worse than champion ' + champMetrics.macro_f1; }

return [{ json: { trained: true, decision: promoted ? 'promoted' : 'rejected', promoted, reason,
  n_train: train.length, n_test: test.length, dropped, features: V,
  classes_json: JSON.stringify(classes), metrics_json: JSON.stringify(metrics),
  champion_metrics_json: JSON.stringify(champMetrics), model_json: JSON.stringify(model) } }];

const t = $('Train & Evaluate').first().json;
const saved = $input.first().json || {};
const esc = s => String(s === null || s === undefined ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const lines = [];
if (!t.trained) {
  lines.push('🧠 <b>Training skipped</b>', esc(t.reason));
} else {
  const m = JSON.parse(t.metrics_json), c = JSON.parse(t.champion_metrics_json);
  lines.push((t.promoted ? '✅ <b>New model promoted</b>' : '⛔ <b>Model rejected</b>') + (saved.model_id ? ' (#' + saved.model_id + ')' : ''));
  lines.push(esc(t.reason), '');
  lines.push('Train/holdout: ' + t.n_train + ' / ' + t.n_test + ', features: ' + t.features);
  lines.push('Accuracy: ' + m.accuracy + ', macro F1: ' + m.macro_f1 + (c ? ' (champion ' + c.macro_f1 + ')' : ''));
  const weak = Object.entries(m.per_class).filter(([, v]) => v.support && v.f1 < 0.6).map(([k, v]) => k + ' (F1 ' + v.f1 + ')');
  if (weak.length) lines.push('Weak classes: ' + esc(weak.join(', ')));
}
if (t.dropped && t.dropped.length) lines.push('Ignored (fewer than 5 examples): ' + esc(t.dropped.join(', ')));
return [{ json: { text: lines.join('\n') } }];

const r = $input.first().json;
const esc = s => String(s === null || s === undefined ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const alerts = [];
if (r.model_id === null || r.model_id === undefined) alerts.push('No active model. Predictions return 503 until a model is trained.');
if (r.n_24h >= 20 && Number(r.low_confidence_rate) > 0.4) alerts.push('Low-confidence rate is ' + Math.round(r.low_confidence_rate * 100) + '% over ' + r.n_24h + ' predictions. The model may not cover new topics.');
if (r.n_feedback_7d >= 20 && r.feedback_accuracy !== null && Number(r.feedback_accuracy) < 0.7) alerts.push('Accuracy on human feedback is ' + Math.round(r.feedback_accuracy * 100) + '% over ' + r.n_feedback_7d + ' corrections in 7 days.');
if (r.n_24h >= 50 && r.n_baseline >= 50 && Number(r.label_shift) > 0.3) alerts.push('Label distribution shifted by ' + r.label_shift + ' (total variation) compared with the previous 7 days.');
if (!alerts.length) return [];
const lines = ['📉 <b>ML service needs attention</b>', ''];
for (const a of alerts) lines.push('• ' + esc(a));
lines.push('', 'Last 24 h: ' + r.n_24h + ' predictions, average confidence ' + r.avg_confidence + '. Model #' + (r.model_id ?? '-') + ', ' + (r.model_age_days ?? '-') + ' days old, ' + r.total_examples + ' training examples.');
return [{ json: { text: lines.join('\n') } }];

const e = $input.first().json;
const wf = (e.workflow && e.workflow.name) || 'unknown workflow';
const node = (e.execution && e.execution.lastNodeExecuted) || 'unknown node';
const msg = (e.execution && e.execution.error && e.execution.error.message) || 'unknown error';
const url = (e.execution && e.execution.url) || '';
return [{ json: { text: 'WORKFLOW ERROR\n\nWorkflow: ' + wf + '\nFailed node: ' + node + '\nError: ' + String(msg).slice(0, 500) + (url ? '\n' + url : '') } }];
